INSERT INTO `campaigns` (`id`, `title`, `description`, `category`, `goal_amount`, `raised_amount`, `image_url`, `status`, `beneficiaries_count`, `submitted_by`, `created_at`) VALUES ('camp-003', 'Women\'s Skill Development', 'Empower women through vocational training in tailoring, handicrafts, and entrepreneurship. Create sustainable livelihoods for rural women.', 'Women Empowerment', 300000, 180000, 'https://images.unsplash.com/photo-1723564211731-21ceb97443a5?crop=entropy&cs=srgb&fm=jpg&ixid=M3w3NDQ2NDJ8MHwxfHNlYXJjaHwxfHxpbmRpYW4lMjB3b21lbiUyMHNlbGYlMjBoZWxwJTIwZ3JvdXAlMjBtZWV0aW5nfGVufDB8fHx8MTc3MTU4MDEyN3ww&ixlib=rb-4.1.0&q=85', 'active', 300, NULL, '2026-03-21T09:44:11.022001+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `campaigns` (`id`, `title`, `description`, `category`, `goal_amount`, `raised_amount`, `image_url`, `status`, `beneficiaries_count`, `submitted_by`, `created_at`) VALUES ('camp-001', 'Education for Rural Children', 'Provide quality education and learning materials to children in rural areas. Help us build libraries and provide scholarships for underprivileged students.', 'Education', 500000, 325000, 'https://images.pexels.com/photos/18012463/pexels-photo-18012463.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', 'active', 500, NULL, '2026-03-21T09:44:11.022001+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `campaigns` (`id`, `title`, `description`, `category`, `goal_amount`, `raised_amount`, `image_url`, `status`, `beneficiaries_count`, `submitted_by`, `created_at`) VALUES ('camp-002', 'Mobile Healthcare Clinics', 'Bring healthcare to remote villages through mobile medical clinics. Provide free checkups, medicines, and health awareness programs.', 'Healthcare', 800000, 450000, 'https://images.pexels.com/photos/7579824/pexels-photo-7579824.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', 'active', 1200, NULL, '2026-03-21T09:44:11.022001+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `content`, `author`, `image_url`, `category`, `tags`, `published`, `created_at`) VALUES ('blog-002', 'Healthcare Access: Bridging the Gap in Rural India', 'healthcare-access-bridging-the-gap', 'Our mobile health clinics are bringing essential healthcare services to underserved rural communities', 'Access to basic healthcare remains a challenge for millions in rural India. Our mobile health clinic initiative is changing this narrative, one village at a time.
INSERT INTO `blogs` (`id`, `title`, `slug`, `excerpt`, `content`, `author`, `image_url`, `category`, `tags`, `published`, `created_at`) VALUES ('blog-001', 'Transforming Lives Through Education: A Success Story', 'transforming-lives-through-education', 'How a small education initiative transformed into a movement impacting 500+ children in rural Maharashtra', 'In the heart of rural Maharashtra, we witnessed a remarkable transformation. What started as a small initiative to provide books to 50 children has now grown into a full-fledged education program serving over 500 students.
INSERT INTO `activities` (`id`, `title`, `description`, `category`, `media_type`, `media_url`, `gallery_urls`, `event_date`, `location`, `created_at`) VALUES ('0819d919-9e46-4055-b388-0c503f5947e9', 'Rural Education Drive 2026', 'Distributed learning kits, textbooks, and smart tablets to over 500 children across 12 village primary schools.', 'Education', 'image', 'https://images.pexels.com/photos/18012463/pexels-photo-18012463.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/18012458/pexels-photo-18012458.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940", "https://images.pexels.com/photos/7692546/pexels-photo-7692546.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940"]', '2026-05-15', 'Nashik District, Maharashtra', '2026-07-05T04:10:03.088210+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `activities` (`id`, `title`, `description`, `category`, `media_type`, `media_url`, `gallery_urls`, `event_date`, `location`, `created_at`) VALUES ('85265920-f423-462f-8c4f-b9dfa57b82bf', 'Mobile Healthcare & Eye Checkup Camp', 'Free diagnostic medical checkups, eye testing, and medicines provided for elderly residents in underserved communities.', 'Healthcare', 'image', 'https://images.pexels.com/photos/7579824/pexels-photo-7579824.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/7579824/pexels-photo-7579824.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940"]', '2026-06-02', 'Thane Rural, Maharashtra', '2026-07-05T04:10:03.088210+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `activities` (`id`, `title`, `description`, `category`, `media_type`, `media_url`, `gallery_urls`, `event_date`, `location`, `created_at`) VALUES ('f3773fbe-16a3-46d5-8e98-b611974430c4', 'Women Empowerment & Artisans Skill Workshop', 'Trained 80 women in handicraft making, tailoring, and micro-business management to achieve financial independence.', 'Women Empowerment', 'image', 'https://images.unsplash.com/photo-1723564211731-21ceb97443a5?crop=entropy&cs=srgb&fm=jpg&ixid=M3w3NDQ2NDJ8MHwxfHNlYXJjaHwxfHxpbmRpYW4lMjB3b21lbiUyMHNlbGYlMjBoZWxwJTIwZ3JvdXAlMjBtZWV0aW5nfGVufDB8fHx8MTc3MTU4MDEyN3ww&ixlib=rb-4.1.0&q=85', '[]', '2026-06-20', 'Pune District, Maharashtra', '2026-07-05T04:10:03.088210+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `stories` (`id`, `title`, `description`, `featured_image`, `category`, `author`, `created_at`) VALUES ('f4b8f112-40eb-447e-800b-a2736106f208', 'From Village Classroom to Engineering College: Sunita\'s Journey', 'Sunita, born in a small agricultural hamlet, was determined to pursue higher education despite severe financial constraints. Through Charitage Foundation\'s Higher Education Scholarship Initiative, she received full tuition assistance, mentorship, and learning resources. Today, she is in her final year of Computer Engineering and mentoring younger girls in her native village.', 'https://images.pexels.com/photos/18012463/pexels-photo-18012463.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', 'Scholarship', 'Charitage Editorial Team', '2026-07-05T04:10:03.179110+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `stories` (`id`, `title`, `description`, `featured_image`, `category`, `author`, `created_at`) VALUES ('568a8d9c-3879-4e3a-b53b-3d3c4f69bf34', 'Restoring Sight and Hope: Ramesh\'s Cataract Surgery Story', '65-year-old farmer Ramesh lost his sight due to bilateral cataracts, preventing him from tending to his fields. Through Charitage Foundation\'s Free Vision Camp, he underwent successful surgery. \'I can see the sunrise clearly again,\' he says with a smile.', 'https://images.pexels.com/photos/7579824/pexels-photo-7579824.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', 'Healthcare Impact', 'Dr. Ananya Verma', '2026-07-05T04:10:03.179110+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `news` (`id`, `title`, `excerpt`, `content`, `image_url`, `video_url`, `category`, `tags`, `author`, `published_at`, `created_at`) VALUES ('e85b04a2-d316-4fad-87e1-96cdd0bb1cb7', 'Charitage Foundation Recognized for 100% Transparent Philanthropy Model', 'Charitage Foundation awarded top honors for transparent grassroots social impact.', 'Charitage Foundation has been honored at the National Social Innovation Summit for maintaining 0% platform fees and complete financial transparency. Over 98% of direct contributions go straight to ground initiatives.', 'https://images.pexels.com/photos/15597025/pexels-photo-15597025.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', NULL, 'Recognition', '["Award", "Transparency", "Impact"]', 'Media Desk', '2026-07-05T04:10:03.242292+00:00', NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `news` (`id`, `title`, `excerpt`, `content`, `image_url`, `video_url`, `category`, `tags`, `author`, `published_at`, `created_at`) VALUES ('fae8941e-2b86-4e1c-9409-7bbcf57fb921', 'Launch of New Clean Water Initiative in 15 Remote Hamlets', 'Solar water purification plants deployed across rural hamlets.', 'In partnership with local village panchayats, Charitage Foundation has commissioned solar-powered water filtration units providing clean drinking water to over 3,000 households.', 'https://images.pexels.com/photos/7692546/pexels-photo-7692546.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', NULL, 'Initiatives', '["CleanWater", "Sustainability", "Community"]', 'CSR Desk', '2026-07-05T04:10:03.242292+00:00', NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
